FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL; // Botón de arranque (TRUE = arrancar)
    btnParo   : BOOL; // Botón de paro normal (TRUE = detener)
    btnEmerg  : BOOL; // Botón de paro de emergencia (TRUE = detener)
END_VAR

VAR_OUTPUT
    motorOn   : BOOL; // Señal de control hacia el contactor del motor
END_VAR

VAR
    flancoMarcha : R_TRIG; // Detector de flanco para el botón de marcha
END_VAR

// Detectar el flanco de subida de la señal de marcha.
// Esto garantiza que el motor no rearranque automáticamente si el 
// botón de marcha se mantiene presionado tras un paro de emergencia.
flancoMarcha(CLK := btnMarcha);

// Lógica de control: 
// Enclavamiento del motor (flancoMarcha.Q OR motorOn) 
// condicionado a que no haya ninguna señal de paro activa.
// El paro y la emergencia tienen prioridad sobre el arranque.
motorOn := (flancoMarcha.Q OR motorOn) AND NOT btnParo AND NOT btnEmerg;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha (TRUE = pulsado)
    btnParo   : BOOL; // Botón de paro (TRUE = pulsado)
    btnEmerg  : BOOL; // Paro de emergencia (TRUE = pulsado)
END_VAR

VAR_OUTPUT
    motorOn   : BOOL; // Estado del motor (TRUE = encendido)
END_VAR

VAR
    rtMarcha  : R_TRIG; // Detector de flanco ascendente
END_VAR

// Detectar flanco ascendente de la marcha para evitar rearranque automático
// si el botón se mantiene pulsado tras un paro de emergencia.
rtMarcha(CLK := btnMarcha);

// Lógica de control (Enclavamiento)
// Prioridad a las señales de paro (btnParo y btnEmerg)
motorOn := (rtMarcha.Q OR motorOn) AND NOT btnParo AND NOT btnEmerg;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL;  // Botón de marcha
    btnParo : BOOL;    // Botón de paro
    btnEmerg : BOOL;   // Botón de paro de emergencia
END_VAR

VAR_OUTPUT
    motorOn : BOOL;    // Estado del motor (encendido/apagado)
END_VAR

VAR
    emergenciaActiva : BOOL := FALSE;  // Bandera para indicar si hay una parada de emergencia
END_VAR

// Programa principal
IF btnEmerg THEN
    // Si se activa el botón de emergencia, detener el motor y activar la bandera de emergencia
    motorOn := FALSE;
    emergenciaActiva := TRUE;
ELSIF emergenciaActiva THEN
    // Si hay una parada de emergencia activa, mantener el motor apagado
    motorOn := FALSE;
ELSIF btnParo THEN
    // Si se presiona el botón de paro, detener el motor
    motorOn := FALSE;
ELSIF btnMarcha THEN
    // Si se presiona el botón de marcha, encender el motor
    motorOn := TRUE;
END_IF;

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL; // TRUE al pulsar para arrancar
    btnParo   : BOOL; // TRUE al pulsar para detener
    btnEmerg  : BOOL; // TRUE al activar el paro de emergencia
END_VAR

VAR_OUTPUT
    motorOn   : BOOL; // Estado del motor (TRUE = Encendido)
END_VAR

VAR
    rtMarcha  : R_TRIG; // Detector de flanco de subida para el botón de marcha
END_VAR

// Detección de flanco ascendente para evitar el rearranque automático 
// si el botón de marcha se mantiene pulsado tras una emergencia.
rtMarcha(CLK := btnMarcha);

// Lógica de control: Enclavamiento con paro dominante.
// El motor se enciende con el flanco de marcha y se mantiene (motorOn).
// Se detiene inmediatamente si btnParo o btnEmerg son TRUE.
motorOn := (motorOn OR rtMarcha.Q) AND NOT btnParo AND NOT btnEmerg;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL;   // Botón de paro
    btnEmerg : BOOL;  // Botón de paro de emergencia
END_VAR

VAR_OUTPUT
    motorOn : BOOL;   // Estado del motor: encendido o apagado
END_VAR

VAR
    estadoMotor : BOOL := FALSE; // Estado interno del motor
    emergenciaActiva : BOOL := FALSE; // Estado de emergencia
END_VAR

// Lógica de control del motor
IF btnEmerg THEN
    // Si el botón de emergencia está presionado, activar estado de emergencia
    emergenciaActiva := TRUE;
    estadoMotor := FALSE;
ELSIF btnParo THEN
    // Si el botón de paro está presionado, apagar el motor
    estadoMotor := FALSE;
ELSIF btnMarcha AND NOT emergenciaActiva THEN
    // Si el botón de marcha está presionado y no hay emergencia, encender el motor
    estadoMotor := TRUE;
END_IF

// Actualizar la salida del motor
motorOn := estadoMotor;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL;   // Botón de marcha
    btnParo : BOOL;     // Botón de paro
    btnEmerg : BOOL;    // Botón de paro de emergencia
END_VAR

VAR_OUTPUT
    motorOn : BOOL;     // Estado del motor (encendido/apagado)
END_VAR

VAR
    motorLatch : BOOL;  // Latch para mantener el motor encendido
    emergStopLatch : BOOL; // Latch para el estado de paro de emergencia
END_VAR

// Lógica de control del motor
IF btnEmerg THEN
    // Si el botón de emergencia está presionado, activar el latch de emergencia
    emergStopLatch := TRUE;
    motorOn := FALSE; // Apagar el motor inmediatamente
ELSIF btnParo THEN
    // Si el botón de paro está presionado, apagar el motor
    motorOn := FALSE;
ELSIF btnMarcha AND NOT emergStopLatch THEN
    // Si el botón de marcha está presionado y no hay paro de emergencia, encender el motor
    motorLatch := TRUE;
END_IF

// Mantener el motor encendido si el latch está activo
IF motorLatch AND NOT btnParo AND NOT btnEmerg THEN
    motorOn := TRUE;
ELSE
    motorOn := FALSE;
    motorLatch := FALSE; // Resetear el latch si el motor se apaga
END_IF

// Resetear el latch de emergencia si el motor está apagado y no hay emergencia
IF NOT btnEmerg THEN
    emergStopLatch := FALSE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Motor
VAR_INPUT
    btnMarcha : BOOL;   // Botón de marcha
    btnParo : BOOL;     // Botón de paro
    btnEmerg : BOOL;    // Botón de paro de emergencia
END_VAR

VAR_OUTPUT
    motorOn : BOOL;     // Estado del motor (encendido/apagado)
END_VAR

VAR
    motorLatch : BOOL;  // Latch para mantener el motor encendido
    emergStop : BOOL;   // Estado de paro de emergencia
END_VAR

// Lógica de control del motor
IF btnEmerg THEN
    // Si el botón de emergencia está presionado, detener el motor
    motorOn := FALSE;
    emergStop := TRUE;
ELSIF btnParo THEN
    // Si el botón de paro está presionado, detener el motor
    motorOn := FALSE;
ELSIF btnMarcha AND NOT emergStop THEN
    // Si el botón de marcha está presionado y no hay paro de emergencia, arrancar el motor
    motorOn := TRUE;
END_IF

// Actualizar el estado del latch del motor
motorLatch := motorOn;

// Si el motor está encendido, mantenerlo encendido
IF motorLatch THEN
    motorOn := TRUE;
END_IF

// Resetear el estado de paro de emergencia si el motor está apagado
IF NOT motorOn THEN
    emergStop := FALSE;
END_IF

END_FUNCTION_BLOCK
